 static JSONObject sourceRow(JSONObject instrument)throws Exception{JSONObject q=instrument.optJSONObject("quote");if(q==null)q=new JSONObject();String state=quoteState(q);Object price=known(q.opt("price")),change=known(q.opt("changePercent"));if(state.equals("unavailable")){price=JSONObject.NULL;change=JSONObject.NULL;}if(price instanceof Number&&((Number)price).doubleValue()<=0)price=JSONObject.NULL;return new JSONObject().put("instrumentId",instrument.opt("id")).put("code",instrument.opt("code")).put("name",instrument.opt("name")).put("price",price).put("change",change).put("quoteStatus",state).put("quote",new JSONObject(q.toString())).put("instrument",new JSONObject(instrument.toString()));}
