  need(trades.length()<=10000&&quoteInstruments.length()<=10000&&watchInstruments.length()<=10000,"本地风险输入超过10000行，未截取评估");JSONObject quotes=new JSONObject();Map<String,JSONObject> roster=new HashMap<>();for(int i=0;i<quoteInstruments.length();i++){JSONObject r=quoteInstruments.getJSONObject(i);String id=text(r,"id");need(fullId(id)&&!roster.containsKey(id)&&r.opt("quote") instanceof JSONObject,"行情完整身份重复/无效或报价对象缺失");roster.put(id,r);quotes.put(id,r.getJSONObject("quote"));}
