  rows=snapshot.getJSONArray("leaderOverview");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);Object change=known(row.opt("change"));if(!(change instanceof Number))missing++;else if(fullId(text(row,"instrumentId"))&&((Number)change).doubleValue()<=-leader)add(alerts,snapshot,"leader-drop",row,((Number)change).doubleValue()<=-leader*1.6?"high":"medium","龙头涨跌幅",change,-leader);}
